import { readFileSync, writeFileSync, unlinkSync } from 'node:fs';

const articlesPath = 'src/content/articles.ts';
let articles = readFileSync(articlesPath, 'utf8');
articles = articles.replace(
  '  category: string;\n  summary: string;\n',
  '  category: string;\n  tags: readonly string[];\n  audiences: readonly string[];\n  uses: readonly string[];\n  summary: string;\n',
);
articles = articles.replace(
  '  if (metadata.changeLog.length === 0) {\n',
  `  for (const [label, values] of [\n    ["tags", metadata.tags],\n    ["audiences", metadata.audiences],\n    ["uses", metadata.uses],\n  ] as const) {\n    if (values.length === 0) {\n      throw new TypeError(\`${'${label}'} must contain at least one value\`);\n    }\n    const normalized = values.map((value) => value.normalize("NFKC").trim());\n    if (normalized.some((value) => value.length === 0)) {\n      throw new TypeError(\`${'${label}'} must not contain empty values\`);\n    }\n    if (new Set(normalized).size !== normalized.length) {\n      throw new TypeError(\`${'${label}'} must not contain duplicate values\`);\n    }\n  }\n  if (metadata.changeLog.length === 0) {\n`,
);
articles = articles.replace(
  '  category: "育児用品",\n  summary:',
  '  category: "育児用品",\n  tags: ["紙おむつ", "新生児", "パンパース"],\n  audiences: ["新生児の保護者", "出産準備中の人"],\n  uses: ["毎日使う", "肌への配慮を比較"],\n  summary:',
);
writeFileSync(articlesPath, articles);

writeFileSync(
  'src/lib/article-discovery.ts',
  `import type { ArticleMetadata } from "../content/articles";\n\nexport interface ArticleDiscoveryState {\n  query: string;\n  category?: string;\n  tag?: string;\n}\n\nexport function normalizeDiscoveryText(value: string): string {\n  return value.normalize("NFKC").toLocaleLowerCase("ja-JP").trim().replace(/\\s+/g, " ");\n}\n\nexport function matchesArticle(\n  article: ArticleMetadata,\n  state: ArticleDiscoveryState,\n): boolean {\n  if (state.category && article.category !== state.category) return false;\n  if (state.tag && !article.tags.includes(state.tag)) return false;\n  const query = normalizeDiscoveryText(state.query);\n  if (!query) return true;\n  const haystack = normalizeDiscoveryText([\n    article.title,\n    article.headline,\n    article.summary,\n    article.category,\n    ...article.tags,\n    ...article.audiences,\n    ...article.uses,\n  ].join(" "));\n  return query.split(" ").every((term) => haystack.includes(term));\n}\n\nexport function parseDiscoveryState(\n  params: URLSearchParams,\n  validCategories: readonly string[],\n  validTags: readonly string[],\n): ArticleDiscoveryState {\n  const category = params.get("category")?.normalize("NFKC").trim();\n  const tag = params.get("tag")?.normalize("NFKC").trim();\n  return {\n    query: params.get("q")?.slice(0, 100) ?? "",\n    category: category && validCategories.includes(category) ? category : undefined,\n    tag: tag && validTags.includes(tag) ? tag : undefined,\n  };\n}\n\nexport function discoverySearchParams(state: ArticleDiscoveryState): URLSearchParams {\n  const params = new URLSearchParams();\n  const query = state.query.trim();\n  if (query) params.set("q", query);\n  if (state.category) params.set("category", state.category);\n  if (state.tag) params.set("tag", state.tag);\n  return params;\n}\n`,
);

writeFileSync(
  'src/pages/articles/index.astro',
  `---\nimport BaseLayout from '../../layouts/BaseLayout.astro';\nimport {articleMetadata} from '../../content/articles';\n\nconst categories = [...new Set(articleMetadata.map((article) => article.category))].sort();\nconst tags = [...new Set(articleMetadata.flatMap((article) => article.tags))].sort();\n---\n<BaseLayout title="比較記事一覧｜くらべる商品メモ" description="公式情報と確認できる口コミで商品を比べる記事一覧">\n  <section class="section wrap article-index" data-article-discovery>\n    <p class="eyebrow">Comparison articles</p>\n    <h1>比較記事一覧</h1>\n    <p class="lead">確認できる公式情報と販売ページを起点に、商品を選ぶときの判断材料を整理しています。</p>\n\n    <form class="article-filters" role="search" aria-label="比較記事を検索" data-discovery-form>\n      <label>\n        <span>キーワード</span>\n        <input type="search" name="q" maxlength="100" autocomplete="off" placeholder="商品名・用途・悩みで検索" data-discovery-query />\n      </label>\n      <label>\n        <span>カテゴリ</span>\n        <select name="category" data-discovery-category>\n          <option value="">すべて</option>\n          {categories.map((category) => <option value={category}>{category}</option>)}\n        </select>\n      </label>\n      <label>\n        <span>タグ</span>\n        <select name="tag" data-discovery-tag>\n          <option value="">すべて</option>\n          {tags.map((tag) => <option value={tag}>{tag}</option>)}\n        </select>\n      </label>\n      <button type="button" class="secondary-button" data-discovery-clear>条件をクリア</button>\n    </form>\n    <p class="meta" aria-live="polite" data-discovery-count>{articleMetadata.length}件の記事</p>\n\n    <div class="article-list" data-discovery-results>\n      {articleMetadata.map((article) => (\n        <article\n          class="card article-list-card"\n          data-article-card\n          data-search={[article.title, article.headline, article.summary, article.category, ...article.tags, ...article.audiences, ...article.uses].join(' ').normalize('NFKC').toLocaleLowerCase('ja-JP')}\n          data-category={article.category}\n          data-tags={JSON.stringify(article.tags)}\n        >\n          <span class="tag">{article.category}</span>\n          <h2><a href={article.path}>{article.headline}</a></h2>\n          <p>{article.summary}</p>\n          <ul class="article-tags" aria-label="記事タグ">\n            {article.tags.map((tag) => <li>{tag}</li>)}\n          </ul>\n          <p class="meta">更新日 <time datetime={article.modifiedAt}>{article.modifiedAt}</time></p>\n          <a class="cta" href={article.path}>記事を読む →</a>\n        </article>\n      ))}\n    </div>\n    <div class="card discovery-empty" hidden data-discovery-empty>\n      <h2>条件に合う記事がありません</h2>\n      <p>キーワードを短くするか、カテゴリ・タグをクリアしてください。</p>\n      <button type="button" class="secondary-button" data-discovery-clear>条件をクリア</button>\n    </div>\n  </section>\n\n  <script is:inline>\n    (() => {\n      const root = document.querySelector('[data-article-discovery]');\n      if (!(root instanceof HTMLElement)) return;\n      const query = root.querySelector('[data-discovery-query]');\n      const category = root.querySelector('[data-discovery-category]');\n      const tag = root.querySelector('[data-discovery-tag]');\n      const count = root.querySelector('[data-discovery-count]');\n      const empty = root.querySelector('[data-discovery-empty]');\n      const cards = [...root.querySelectorAll('[data-article-card]')];\n      if (!(query instanceof HTMLInputElement) || !(category instanceof HTMLSelectElement) || !(tag instanceof HTMLSelectElement)) return;\n      const normalize = (value) => value.normalize('NFKC').toLocaleLowerCase('ja-JP').trim().replace(/\\s+/g, ' ');\n      const allowed = (select, value) => [...select.options].some((option) => option.value === value) ? value : '';\n      const initial = new URLSearchParams(location.search);\n      query.value = (initial.get('q') || '').slice(0, 100);\n      category.value = allowed(category, initial.get('category') || '');\n      tag.value = allowed(tag, initial.get('tag') || '');\n      const apply = () => {\n        const terms = normalize(query.value).split(' ').filter(Boolean);\n        let visible = 0;\n        cards.forEach((card) => {\n          if (!(card instanceof HTMLElement)) return;\n          const tags = JSON.parse(card.dataset.tags || '[]');\n          const matches = (!category.value || card.dataset.category === category.value) && (!tag.value || tags.includes(tag.value)) && terms.every((term) => (card.dataset.search || '').includes(term));\n          card.hidden = !matches;\n          if (matches) visible += 1;\n        });\n        if (count) count.textContent = visible + '件の記事';\n        if (empty instanceof HTMLElement) empty.hidden = visible !== 0;\n        const params = new URLSearchParams();\n        if (query.value.trim()) params.set('q', query.value.trim());\n        if (category.value) params.set('category', category.value);\n        if (tag.value) params.set('tag', tag.value);\n        history.replaceState(null, '', location.pathname + (params.size ? '?' + params.toString() : '') + location.hash);\n      };\n      root.querySelector('[data-discovery-form]')?.addEventListener('submit', (event) => event.preventDefault());\n      query.addEventListener('input', apply);\n      category.addEventListener('change', apply);\n      tag.addEventListener('change', apply);\n      root.querySelectorAll('[data-discovery-clear]').forEach((button) => button.addEventListener('click', () => { query.value = ''; category.value = ''; tag.value = ''; apply(); query.focus(); }));\n      apply();\n    })();\n  </script>\n</BaseLayout>\n`,
);

const cssPath = 'src/styles/global.css';
let css = readFileSync(cssPath, 'utf8');
css += `\n.article-filters { display: grid; grid-template-columns: minmax(0, 2fr) repeat(2, minmax(0, 1fr)) auto; gap: 0.8rem; align-items: end; margin: 2rem 0 0.75rem; }\n.article-filters label { display: grid; gap: 0.35rem; font-weight: 750; }\n.article-filters input, .article-filters select { min-height: 48px; width: 100%; border: 1px solid var(--line); border-radius: 6px; background: var(--paper); color: var(--ink); padding: 0.7rem 0.8rem; font: inherit; }\n.secondary-button { min-height: 48px; border: 1px solid var(--ink); border-radius: 6px; background: transparent; color: var(--ink); padding: 0.65rem 0.9rem; font: inherit; font-weight: 800; cursor: pointer; }\n.article-tags { display: flex; flex-wrap: wrap; gap: 0.45rem; padding: 0; list-style: none; }\n.article-tags li { border: 1px solid var(--line); border-radius: 999px; padding: 0.2rem 0.55rem; color: var(--muted); font-size: 0.78rem; }\n.discovery-empty { margin-top: 1rem; }\n[hidden] { display: none !important; }\n@media (max-width: 760px) { .article-filters { grid-template-columns: 1fr; } .article-list-card { max-width: none; } }\n`;
writeFileSync(cssPath, css);

writeFileSync(
  'tests/article-discovery.test.ts',
  `import { readFileSync } from "node:fs";\nimport { describe, expect, it } from "vitest";\nimport { pampersNewbornArticle } from "../src/content/articles";\nimport { discoverySearchParams, matchesArticle, normalizeDiscoveryText, parseDiscoveryState } from "../src/lib/article-discovery";\n\ndescribe("article discovery", () => {\n  it("normalizes width, case and whitespace", () => {\n    expect(normalizeDiscoveryText("  ＰＡＭＰＥＲＳ   新生児 ")).toBe("pampers 新生児");\n  });\n  it("matches typed metadata across query, category and tag", () => {\n    expect(matchesArticle(pampersNewbornArticle, { query: "パンパース 新生児", category: "育児用品", tag: "紙おむつ" })).toBe(true);\n    expect(matchesArticle(pampersNewbornArticle, { query: "飲料" })).toBe(false);\n  });\n  it("ignores unknown query parameters and serializes known state", () => {\n    const parsed = parseDiscoveryState(new URLSearchParams("q=新生児&category=unknown&tag=紙おむつ"), ["育児用品"], ["紙おむつ"]);\n    expect(parsed).toEqual({ query: "新生児", category: undefined, tag: "紙おむつ" });\n    expect(discoverySearchParams(parsed).toString()).toBe("q=%E6%96%B0%E7%94%9F%E5%85%90&tag=%E7%B4%99%E3%81%8A%E3%82%80%E3%81%A4");\n  });\n  it("renders every article before JavaScript and exposes accessible filters", () => {\n    const html = readFileSync("dist/articles/index.html", "utf8");\n    expect(html).toContain('role="search"');\n    expect(html).toContain('data-article-card');\n    expect(html).toContain(pampersNewbornArticle.path);\n    expect(html).toContain("条件に合う記事がありません");\n    expect(html).toContain("紙おむつ");\n  });\n});\n`,
);

unlinkSync('.github/agent-apply-article-discovery.mjs');
